<template><div v-if="open" class="modal-backdrop" role="presentation" @click.self="$emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="export-title"><h2 id="export-title">导出绘图</h2><label>格式<select v-model="target"><option value="png">PNG</option><option value="svg">SVG</option></select></label><label><input v-model="transparent" type="checkbox">透明背景</label><label><input v-model="selectedOnly" type="checkbox">仅导出选区</label><footer class="panel__footer"><button class="button" type="button" @click="$emit('close')">取消</button><button class="button button--primary" type="button" @click="$emit('export', { target, transparent, selectedOnly })">导出</button></footer></section></div></template>
<script setup lang="ts">import { ref } from 'vue'; defineProps<{ open: boolean }>(); defineEmits<{ close: []; export: [request: { target: 'png' | 'svg'; transparent: boolean; selectedOnly: boolean }] }>(); const target = ref<'png' | 'svg'>('png'); const transparent = ref(true); const selectedOnly = ref(false);</script>
